document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const t=document.getElementById("event-form"),i=document.getElementById("event-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const a=parseInt(document.getElementById("event-managers").value),r=parseFloat(document.getElementById("office-setup").value),o=parseFloat(document.getElementById("equipment").value),l=parseFloat(document.getElementById("marketing-working-capital").value),d=parseFloat(document.getElementById("monthly-events").value),c=parseFloat(document.getElementById("avg-event-budget").value),v=parseFloat(document.getElementById("agency-margin").value),p=parseFloat(document.getElementById("manager-commission").value),g=parseFloat(document.getElementById("monthly-rent").value),m=parseFloat(document.getElementById("base-salaries").value),u=parseFloat(document.getElementById("marketing-costs").value),f=parseFloat(document.getElementById("other-costs").value);if(a<=0||d<=0||c<=0||v<=0)return i.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const $=r+o+l,b=d*c,w=b*v/100,y=w*p/100,h=w-y,k=12*w,E=g+m+u+f,I=E+y,M=h-E,B=12*M,F=B/k*100,x=$/B,P=B/$*100,D=k/a,A=d/a,C=w/d,L=A/5*100;let O="info";B<0?O="warning":F>30&&(O="success");let S="info";P<30?S="warning":P>60&&(S="success");let R="info";L<60?R="warning":L>85&&(R="success"),i.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🎉 Event Management Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n($),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(M),`Margin: ${e(F)}`,O)}\n            ${s("⏱️ Payback Period",`${x.toFixed(1)} years`,`ROI: ${e(P)}`,x<=1?"success":"warning")}\n            ${s("📊 Team Utilization",e(L),`${A.toFixed(1)} events/manager`,R)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Office lease & setup</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment (tech, furniture)</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial marketing & working capital</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n($)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Total event budgets (${d} × ${n(c)})</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Agency gross margin (${e(v)})</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Manager commissions (${e(p)})</span>\n                  <span>-${n(y)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Net Agency Margin</strong></span>\n                  <span><strong>${n(h)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Office rent</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Base staff salaries</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & advertising</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Fixed Expenses</strong></span>\n                  <span><strong>${n(E)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Team Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per manager: <strong>${n(D)}/year</strong><br>\n                Events per manager: <strong>${A.toFixed(1)}/month</strong><br>\n                Margin per event: <strong>${n(C)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${B>0?"success":"warning"}">\n              <h6>📊 Project Analysis</h6>\n              <div class="metric-subtitle">\n                Average event budget: <strong>${n(c)}</strong><br>\n                Agency margin: <strong>${e(v)}</strong><br>\n                Manager commission: <strong>${e(p)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(B)}</strong><br>\n                Weekly profit: <strong>${n(B/52)}</strong><br>\n                Daily profit: <strong>${n(B/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                +1 event/month impact: <strong>+${n(12*C*(1-p/100))}/year</strong><br>\n                +$1,000 budget increase: <strong>+${n(1e3*v/100*d*12*(1-p/100))}/year</strong><br>\n                +1 manager potential: <strong>+${n(D*(1-p/100)-12*m/a)}/year</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${F<25?"<li>⚠️ Low profitability. Consider increasing margins or reducing manager commission rates.</li>":""}\n              ${L<60?"<li>📍 Low team utilization. Improve marketing or hire fewer managers initially.</li>":""}\n              ${x>1.5?"<li>⏰ Long payback period. Optimize startup costs or increase project volume.</li>":""}\n              ${L>90?"<li>✅ High utilization! Consider team expansion or price increases.</li>":""}\n              ${F>35?"<li>🎉 Excellent profitability! Consider expanding service offerings or locations.</li>":""}\n              <li>💼 Implement CRM system for effective project and client management.</li>\n              <li>📱 Develop strong online portfolio and social media presence.</li>\n              <li>🎯 Specialize in profitable niches: corporate events, conferences.</li>\n              <li>🤝 Build partnerships with venues, catering, and decoration vendors.</li>\n              <li>📈 Implement KPI system for managers: project profitability, client satisfaction.</li>\n              <li>⭐ Invest in team training for new trends and technologies.</li>\n              <li>🎪 Consider additional services: decor, catering, technical support.</li>\n              <li>🌐 Implement digital solutions: virtual events, participant mobile apps.</li>\n              <li>💎 Create premium service packages for VIP clients.</li>\n              <li>🔄 Develop vendor partnership programs for additional revenue streams.</li>\n              <li>📋 Standardize processes and create service packages for efficiency.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.eventBusinessData={"Number of Event Managers":a,"Total Investment ($)":$,"Monthly Gross Margin ($)":w,"Monthly Expenses ($)":I,"Monthly Profit ($)":M,"Annual Profit ($)":B,"Profit Margin (%)":F,"Annual ROI (%)":P,"Payback Period (years)":x,"Monthly Events":d,"Events per Manager":A,"Agency Margin (%)":v,"Average Event Budget ($)":c,"Revenue per Manager ($)":D}}),window.downloadCSV=function(){if(!window.eventBusinessData)return;const n=Object.entries(window.eventBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="event-management-business-plan.csv",s.click()}});